func HandleReassembleTranscript(stdin io.Reader, stdout io.Writer, chunker transcriptChunker) error {
	input, err := ReadJSON[ChunkResponse](stdin)
	if err != nil {
		return err
	}
	data, err := chunker.ReassembleTranscript(input.Chunks)
	if err != nil {
