	}
	var text compactTextBlock
	if err := json.Unmarshal(lines[2].Content[0], &text); err != nil {
		t.Fatal(err)
	}
	if text.Type != "text" || text.Text != "done" {
		t.Fatalf("text block = %+v", text)
	}
}

