package amp

import (
	"encoding/json"
	"fmt"
	"strconv"
	"strings"
	"time"
)

// ThreadUnixMillis is an epoch timestamp encoded as milliseconds.
type ThreadUnixMillis int64

func (m ThreadUnixMillis) Time() time.Time {
	if m == 0 {
		return time.Time{}
	}
	return time.UnixMilli(int64(m)).UTC()
}

