	if err := HandleParseHook([]string{"--hook", "session_start"}, strings.NewReader(`{}`), &out, testHooks{event: &EventJSON{Type: 1, SessionID: "id"}}); err != nil || !strings.Contains(out.String(), `"type":1`) {
